add_action( 'woocommerce_product_query', 'perfectpixel_automatic_sale_category' );
add_filter( 'woocommerce_product_subcategories_hide_empty', 'perfectpixel_automatic_sale_category_visible' );

function perfectpixel_automatic_sale_category( $q ) {
	$category = (int) '{{sale_category_id}}';
	if ( ! $category || ! is_product_category() || get_queried_object_id() !== $category ) {
		return;
	}
	$ids = wc_get_product_ids_on_sale();
	// Drop the (empty) category filter and list the products on sale instead.
	$q->set( 'product_cat', '' );
	$q->set( 'tax_query', array() );
	$q->set( 'post__in', $ids ? array_values( array_unique( array_map( 'intval', $ids ) ) ) : array( 0 ) );
}

function perfectpixel_automatic_sale_category_visible( $hide_empty ) {
	return (int) '{{sale_category_id}}' ? false : $hide_empty;
}
